INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Bataille d''Alésia', 'bataille-d-alesia-FR', '0052-09-01', '0052-09-01', 'La bataille d''Alésia oppose les forces de Vercingétorix à l''armée romaine de Jules César et marque la défaite décisive de la résistance gauloise.', NULL, 6),
('Clovis devient roi des Francs', 'clovis-devient-roi-des-francs', '0481-01-01', '0481-01-01', 'Clovis devient roi des Francs et fonde la dynastie mérovingienne.', NULL, 5),
('Baptême de Clovis', 'bapteme-de-clovis', '0496-12-25', '0496-12-25', 'Le baptême de Clovis à Reims marque sa conversion au christianisme nicéen.', NULL, 23),
('Bataille de Poitiers', 'bataille-de-poitiers-FR', '0732-10-01', '0732-10-01', 'La bataille de Poitiers oppose les forces franques dirigées par Charles Martel aux forces omeyyades.', NULL, 6),
('Couronnement de Charlemagne', 'couronnement-de-charlemagne-FR', '0800-12-25', '0800-12-25', 'Charlemagne est couronné empereur d''Occident par le pape Léon III à Rome.', NULL, 4),
('Traité de Verdun', 'traite-de-verdun-FR', '0843-08-10', '0843-08-10', 'Le traité de Verdun partage l''Empire carolingien entre les trois petits-fils de Charlemagne.', NULL, 14),
('Siège de Paris par les Vikings', 'siege-de-paris-par-les-vikings-FR', '0885-11-24', '0886-02-01', 'Les Vikings assiègent Paris pendant plusieurs mois avant de négocier leur départ.', NULL, 6),
('Création du duché de Normandie', 'creation-du-duche-de-normandie', '0911-01-01', '0911-01-01', 'Le traité de Saint-Clair-sur-Epte établit le duché de Normandie autour de Rollon.', NULL, 17),
('Hugues Capet devient roi', 'hugues-capet-devient-roi', '0987-07-03', '0987-07-03', 'Hugues Capet est élu roi des Francs et inaugure la dynastie capétienne.', NULL, 5),
('Bataille de Bouvines', 'bataille-de-bouvines-FR', '1214-07-27', '1214-07-27', 'La bataille de Bouvines oppose notamment l''armée de Philippe Auguste à une coalition menée par l''empereur Otton IV et le roi Jean sans Terre.', NULL, 6),
('Guerre de Cent Ans', 'guerre-de-cent-ans-FR', '1337-01-01', '1453-10-19', 'La guerre de Cent Ans est un long conflit opposant principalement les royaumes de France et d''Angleterre entre 1337 et 1453.', NULL, 6),
('Jeanne d''Arc libère Orléans', 'jeanne-d-arc-libere-orleans', '1429-04-29', '1429-05-08', 'Jeanne d''Arc participe à la levée du siège d''Orléans pendant la guerre de Cent Ans.', NULL, 6),
('Bataille de Marignan', 'bataille-de-marignan-FR', '1515-09-13', '1515-09-14', 'La bataille de Marignan oppose les forces françaises aux Suisses et constitue une victoire majeure du règne de François Ier.', NULL, 6),
('Édit de Nantes', 'edit-de-nantes', '1598-04-13', '1598-04-13', 'Henri IV promulgue l''édit de Nantes, accordant des droits et garanties aux protestants français.', NULL, 14),
('Louis XIV commence son gouvernement personnel', 'louis-xiv-gouvernement-personnel', '1661-03-09', '1661-03-09', 'Après la mort de Mazarin, Louis XIV décide de gouverner personnellement le royaume de France.', NULL, 22),
('Prise de la Bastille', 'prise-de-la-bastille', '1789-07-14', '1789-07-14', 'La prise de la Bastille, le 14 juillet 1789 à Paris, constitue un événement majeur du début de la Révolution française.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQtsZwZ-6JgZwcjKMQodeYdMKi0Gqi7Ekw-kYl8BnB76A&s=10', 8),
('Déclaration des droits de l''homme et du citoyen', 'declaration-des-droits-de-l-homme-et-du-citoyen-FR', '1789-08-26', '1789-08-26', 'L''Assemblée nationale constituante adopte la Déclaration des droits de l''homme et du citoyen.', NULL, 22),
('Proclamation de la Première République', 'proclamation-de-la-premiere-republique', '1792-09-21', '1792-09-21', 'La Convention nationale abolit la monarchie et proclame la République française.', NULL, 22),
('Exécution de Louis XVI', 'execution-de-louis-xvi', '1793-01-21', '1793-01-21', 'Louis XVI est exécuté place de la Révolution à Paris pendant la Révolution française.', NULL, 2),
('Sacre de Napoléon Ier', 'sacre-de-napoleon-ier-FR', '1804-12-02', '1804-12-02', 'Napoléon Bonaparte est sacré empereur des Français lors d''une cérémonie à Notre-Dame de Paris.', NULL, 4),
('Bataille des Champs Catalauniques', 'bataille-des-champs-catalauniques-FR', '0451-01-01', '0451-01-01', 'Les forces romaines et leurs alliés affrontent les Huns d''Attila lors d''une bataille majeure en Gaule.', NULL, 7),
('Bataille de Vouillé', 'bataille-de-vouille-FR', '0507-01-01', '0507-01-01', 'Clovis remporte une victoire contre les Wisigoths et étend son royaume vers le sud de la Gaule.', NULL, 7),
('Pépin le Bref devient roi', 'pepin-le-bref-devient-roi-FR', '0751-11-01', '0751-11-01', 'Pépin le Bref devient roi des Francs, mettant fin à la dynastie mérovingienne.', NULL, 5),
('Mort de Charlemagne', 'mort-de-charlemagne-FR', '0814-01-28', '0814-01-28', 'Charlemagne meurt à Aix-la-Chapelle après avoir profondément marqué l''histoire politique et culturelle de l''Europe occidentale.', NULL, 2),
('Invasions vikings en Francie occidentale', 'invasions-vikings-en-francie-occidentale-FR', '0840-01-01', '0911-01-01', 'Les raids vikings se multiplient sur les côtes et les fleuves de la Francie occidentale.', NULL, 13),
('Conquête de l''Angleterre par Guillaume le Conquérant', 'conquete-de-l-angleterre-par-guillaume-le-conquerant-FR', '1066-10-14', '1066-10-14', 'Guillaume, duc de Normandie, remporte la bataille d''Hastings et conquiert le trône d''Angleterre.', NULL, 12),
('Début de la construction de Notre-Dame de Paris', 'debut-construction-notre-dame-de-paris', '1163-01-01', '1163-01-01', 'La construction de la cathédrale Notre-Dame de Paris commence sous l''épiscopat de Maurice de Sully.', NULL, 17),
('Louis IX devient roi', 'louis-ix-devient-roi', '1226-11-29', '1226-11-29', 'Louis IX, futur Saint Louis, devient roi de France.', NULL, 5),
('Peste noire en France', 'peste-noire-en-france-FR', '1348-01-01', '1348-01-01', 'La peste noire atteint la France et provoque une catastrophe démographique majeure.', NULL, 21),
('Bataille d''Azincourt', 'bataille-d-azincourt-FR', '1415-10-25', '1415-10-25', 'L''armée anglaise remporte une victoire majeure contre les forces françaises pendant la guerre de Cent Ans.', NULL, 7),
('Fin de la guerre de Cent Ans', 'fin-de-la-guerre-de-cent-ans-FR', '1453-10-19', '1453-10-19', 'La reprise de Bordeaux marque traditionnellement la fin de la guerre de Cent Ans.', NULL, 6),
('Début des guerres d''Italie', 'debut-des-guerres-d-italie-FR', '1494-09-01', '1494-09-01', 'Charles VIII lance une expédition en Italie, ouvrant une longue période de conflits impliquant la monarchie française.', NULL, 6),
('Ordonnance de Villers-Cotterêts', 'ordonnance-de-villers-cotterets', '1539-08-10', '1539-08-10', 'François Ier impose notamment l''usage du français dans les actes administratifs et judiciaires du royaume.', NULL, 22),
('Début des guerres de Religion', 'debut-des-guerres-de-religion', '1562-03-01', '1562-03-01', 'Les tensions entre catholiques et protestants dégénèrent en une série de guerres civiles en France.', NULL, 6),
('Assassinat d''Henri IV', 'assassinat-d-henri-iv', '1610-05-14', '1610-05-14', 'Henri IV est assassiné à Paris par François Ravaillac.', NULL, 2),
('Révocation de l''édit de Nantes', 'revocation-de-l-edit-de-nantes', '1685-10-18', '1685-10-18', 'Louis XIV révoque l''édit de Nantes par l''édit de Fontainebleau.', NULL, 22),
('Début de publication de l''Encyclopédie', 'debut-publication-de-l-encyclopedie', '1751-07-01', '1751-07-01', 'Diderot et d''Alembert commencent la publication de l''Encyclopédie, œuvre majeure des Lumières.', NULL, 24),
('Ouverture des États généraux', 'ouverture-des-etats-generaux', '1789-05-05', '1789-05-05', 'Louis XVI ouvre les États généraux à Versailles dans un contexte de crise financière et politique.', NULL, 22),
('Serment du Jeu de paume', 'serment-du-jeu-de-paume', '1789-06-20', '1789-06-20', 'Les députés jurent de ne pas se séparer avant d''avoir donné une constitution à la France.', NULL, 22),
('Abolition des privilèges', 'abolition-des-privileges', '1789-08-04', '1789-08-04', 'L''Assemblée constituante abolit les privilèges féodaux lors de la nuit du 4 août.', NULL, 22),
('Bataille de Valmy', 'bataille-de-valmy-FR', '1792-09-20', '1792-09-20', 'L''armée française remporte une victoire majeure contre les forces prussiennes.', NULL, 7),
('Chute de Robespierre', 'chute-de-robespierre', '1794-07-27', '1794-07-27', 'Robespierre est renversé lors de la journée du 9 Thermidor, mettant fin à la période de la Terreur.', NULL, 10),
('Bataille de Waterloo', 'bataille-de-waterloo-FR', '1815-06-18', '1815-06-18', 'Napoléon est définitivement vaincu lors de la bataille de Waterloo.', NULL, 7),
('Révolution de Juillet', 'revolution-de-juillet', '1830-07-27', '1830-07-29', 'Les Trois Glorieuses provoquent la chute de Charles X et l''avènement de la monarchie de Juillet.', NULL, 8),
('Révolution de Février', 'revolution-de-fevrier', '1848-02-22', '1848-02-24', 'Une révolution renverse la monarchie de Juillet et conduit à la proclamation de la Deuxième République.', NULL, 8),
('Défaite de Sedan', 'defaite-de-sedan-FR', '1870-09-02', '1870-09-02', 'L''armée française capitule à Sedan pendant la guerre franco-prussienne.', NULL, 7),
('Proclamation de la Troisième République', 'proclamation-de-la-troisieme-republique', '1870-09-04', '1870-09-04', 'La République est proclamée à Paris après la chute du Second Empire.', NULL, 22),
('Construction de la tour Eiffel', 'construction-de-la-tour-eiffel', '1887-01-28', '1889-03-31', 'La tour Eiffel est construite à Paris pour l''Exposition universelle de 1889.', NULL, 17),
('Début de la Première Guerre mondiale', 'debut-de-la-premiere-guerre-mondiale-FR', '1914-08-03', '1914-08-03', 'L''Allemagne déclare la guerre à la France, marquant l''entrée officielle de la France dans la Première Guerre mondiale.', NULL, 6),
('Libération de Paris', 'liberation-de-paris-FR', '1944-08-19', '1944-08-25', 'Paris est libéré par les forces françaises et alliées après plusieurs jours d''insurrection et de combats.', NULL, 6);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Révolution brabançonne', 'revolution-brabanconne', '1789-10-24', '1790-12-03', 'La révolution brabançonne éclate contre les réformes de l''empereur Joseph II et conduit à la formation des États belgiques unis, première expérience d''un État belge indépendant des Pays-Bas autrichiens.', NULL, 8),
('Révolution belge', 'revolution-belge-BE', '1830-08-25', '1831-07-21', 'La révolution belge de 1830 provoque la séparation des provinces méridionales du Royaume uni des Pays-Bas et conduit à la création de l''État belge indépendant.', NULL, 8),
('Indépendance de la Belgique', 'independance-de-la-belgique', '1830-10-04', '1830-10-04', 'Le gouvernement provisoire proclame l''indépendance de la Belgique vis-à-vis du Royaume uni des Pays-Bas.', NULL, 11),
('Constitution belge', 'constitution-belge', '1831-02-07', '1831-02-07', 'Le Congrès national adopte la Constitution belge, qui établit les institutions du nouvel État et organise une monarchie constitutionnelle.', NULL, 22),
('Prestation de serment de Léopold Ier', 'prestation-serment-leopold-i', '1831-07-21', '1831-07-21', 'Léopold de Saxe-Cobourg-Gotha prête serment comme premier roi des Belges devant le Congrès national, marquant l''établissement de la monarchie belge.', NULL, 4),
('Traité des XXIV Articles', 'traite-des-xxiv-articles-BE', '1839-04-19', '1839-04-19', 'Le traité des XXIV Articles règle définitivement la séparation entre la Belgique et les Pays-Bas et fixe notamment les frontières internationales du nouvel État belge.', NULL, 14),
('Fondation de l''État indépendant du Congo', 'fondation-etat-independant-congo-BE', '1885-02-26', '1885-02-26', 'La conférence de Berlin reconnaît l''État indépendant du Congo comme possession personnelle du roi Léopold II, ouvrant une période de domination belge au Congo qui prendra fin avec l''annexion par la Belgique en 1908.', NULL, 16),
('Exposition internationale de Bruxelles', 'exposition-internationale-bruxelles-1897', '1897-04-10', '1897-11-08', 'L''Exposition internationale de Bruxelles de 1897 présente les réalisations industrielles, scientifiques et culturelles de la Belgique et accueille des visiteurs internationaux.', NULL, 24),
('Annexion de l''État indépendant du Congo', 'annexion-etat-independant-congo-BE', '1908-11-15', '1908-11-15', 'La Belgique annexe officiellement l''État indépendant du Congo, qui devient le Congo belge sous l''administration de l''État belge.', NULL, 12),
('Invasion allemande de la Belgique', 'invasion-allemande-belgique-1914-BE', '1914-08-04', '1914-10-16', 'L''Allemagne envahit la Belgique au début de la Première Guerre mondiale malgré la neutralité belge, entraînant la résistance de l''armée belge et l''occupation d''une grande partie du territoire.', NULL, 13),
('Bataille de Liège', 'bataille-de-liege-BE', '1914-08-05', '1914-08-16', 'La bataille de Liège oppose l''armée belge aux forces allemandes lors de l''invasion de la Belgique en 1914 et constitue l''un des premiers affrontements majeurs de la Première Guerre mondiale.', NULL, 7),
('Bataille de l''Yser', 'bataille-de-lyser-BE', '1914-10-16', '1914-10-31', 'La bataille de l''Yser oppose les forces belges et alliées à l''armée allemande. L''ouverture des écluses de l''Yser contribue à inonder la plaine et permet de stabiliser le front belge.', NULL, 7),
('Traité de Versailles', 'traite-de-versailles-BE', '1919-06-28', '1919-06-28', 'Le traité de Versailles met officiellement fin à l''état de guerre entre l''Allemagne et les puissances alliées et prévoit notamment des dispositions territoriales concernant la Belgique.', NULL, 14),
('Invasion allemande de la Belgique en 1940', 'invasion-allemande-belgique-1940-BE', '1940-05-10', '1940-05-28', 'L''Allemagne nazie envahit la Belgique pendant la Seconde Guerre mondiale. Après dix-huit jours de combats, l''armée belge capitule le 28 mai 1940.', NULL, 13),
('Libération de Bruxelles', 'liberation-de-bruxelles', '1944-09-03', '1944-09-04', 'Les forces alliées libèrent Bruxelles au début de septembre 1944 après le retrait des forces allemandes. La capitale est reprise avec l''entrée des troupes britanniques et des unités de la résistance.', NULL, 12),
('Question royale', 'question-royale', '1945-05-08', '1951-07-16', 'La question royale porte sur le retour du roi Léopold III après la Seconde Guerre mondiale et provoque une importante crise politique et sociale en Belgique, qui aboutit à son abdication en 1951.', NULL, 22),
('Traité de Rome et naissance de la CEE', 'traite-de-rome-cee-BE', '1957-03-25', '1957-03-25', 'La Belgique signe les traités de Rome avec cinq autres États européens, participant à la création de la Communauté économique européenne et de la Communauté européenne de l''énergie atomique.', NULL, 14),
('Indépendance du Congo belge', 'independance-du-congo-belge-BE', '1960-06-30', '1960-06-30', 'Le Congo belge accède à l''indépendance après plusieurs années de montée des revendications anticoloniales et devient la République du Congo.', NULL, 11),
('Fédéralisation de la Belgique', 'federalisation-de-la-belgique', '1970-12-24', '1993-07-05', 'Une succession de réformes institutionnelles transforme progressivement la Belgique d''un État unitaire en un État fédéral composé de communautés et de régions.', NULL, 22),
('Création de l''Union économique belgo-luxembourgeoise', 'union-economique-belgo-luxembourgeoise-BE', '1921-07-25', '1921-07-25', 'La Belgique et le Luxembourg concluent la convention créant l''Union économique belgo-luxembourgeoise, qui établit une coopération économique et monétaire étroite entre les deux pays.', NULL, 25);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Serments de Strasbourg', 'serments-de-strasbourg-AL', '0842-02-14', '0842-02-14', 'Louis le Germanique et Charles le Chauve prêtent les serments de Strasbourg contre leur frère Lothaire Ier, événement majeur dans la formation politique et linguistique de l''Europe occidentale.', NULL, 14),
('Traité de Verdun', 'traite-de-verdun-AL', '0843-08-10', '0843-08-10', 'Le traité de Verdun partage l''Empire carolingien entre les trois petits-fils de Charlemagne et attribue à Louis le Germanique la Francie orientale.', NULL, 14),
('Couronnement impérial d''Otton Ier', 'couronnement-imperial-otton-ier-AL', '0962-02-02', '0962-02-02', 'Otton Ier est couronné empereur à Rome par le pape Jean XII, événement traditionnellement associé à la fondation du Saint-Empire romain germanique.', NULL, 4),
('Querelle des Investitures', 'querelle-des-investitures-AL', '1075-01-01', '1122-01-01', 'La Querelle des Investitures oppose les empereurs du Saint-Empire à la papauté au sujet de la nomination des évêques et du pouvoir politique et religieux.', NULL, 23),
('Marche de Canossa', 'marche-de-canossa-AL', '1077-01-25', '1077-01-27', 'L''empereur Henri IV se rend à Canossa afin d''obtenir la levée de son excommunication auprès du pape Grégoire VII.', NULL, 23),
('Concordat de Worms', 'concordat-de-worms-AL', '1122-09-23', '1122-09-23', 'Le concordat de Worms met fin à la Querelle des Investitures entre l''empereur Henri V et le pape Calixte II.', NULL, 14),
('Début du règne de Frédéric Barberousse', 'debut-regne-frederic-barberousse', '1152-03-04', '1152-03-04', 'Frédéric Ier, dit Barberousse, devient roi des Romains et entreprend de renforcer l''autorité impériale au sein du Saint-Empire.', NULL, 5),
('Bulle d''Or', 'bulle-d-or', '1356-01-01', '1356-01-01', 'La Bulle d''Or de Charles IV fixe les règles de l''élection du roi des Romains et renforce le rôle des princes-électeurs du Saint-Empire.', NULL, 22),
('Épidémie de peste noire', 'peste-noire-dans-le-saint-empire', '1348-01-01', '1352-01-01', 'La peste noire atteint les territoires du Saint-Empire et provoque une catastrophe démographique et sociale majeure.', NULL, 21),
('Invention de l''imprimerie à caractères mobiles', 'invention-imprimerie-gutenberg', '1450-01-01', '1455-01-01', 'Johannes Gutenberg perfectionne à Mayence l''imprimerie à caractères métalliques mobiles, transformant durablement la diffusion des textes en Europe.', NULL, 19),
('Début de la Réforme protestante', 'debut-reforme-protestante', '1517-10-31', '1517-10-31', 'Martin Luther publie traditionnellement ses 95 thèses à Wittenberg, événement associé au début de la Réforme protestante.', NULL, 23),
('Diète de Worms', 'diete-de-worms', '1521-01-28', '1521-05-25', 'La Diète de Worms examine les positions de Martin Luther, qui refuse de rétracter ses écrits devant l''empereur Charles Quint.', NULL, 23),
('Guerre des Paysans allemands', 'guerre-paysans-allemands', '1524-01-01', '1525-05-01', 'La guerre des Paysans allemands voit de nombreuses communautés rurales se soulever dans différentes régions du Saint-Empire.', NULL, 9),
('Paix d''Augsbourg', 'paix-augsbourg', '1555-09-25', '1555-09-25', 'La paix d''Augsbourg établit un compromis religieux au sein du Saint-Empire entre princes catholiques et luthériens.', NULL, 14),
('Début de la guerre de Trente Ans', 'debut-guerre-trente-ans-AL', '1618-05-23', '1618-05-23', 'La défenestration de Prague contribue au déclenchement de la guerre de Trente Ans, qui ravage une grande partie de l''Europe centrale.', NULL, 6),
('Paix de Westphalie', 'paix-de-westphalie-AL', '1648-10-24', '1648-10-24', 'Les traités de Westphalie mettent fin à la guerre de Trente Ans et réorganisent l''équilibre politique et religieux du Saint-Empire.', NULL, 14),
('Établissement de la monarchie prussienne', 'etablissement-monarchie-prussienne', '1701-01-18', '1701-01-18', 'Frédéric III de Brandebourg devient roi en Prusse sous le nom de Frédéric Ier, renforçant la position de la Prusse parmi les États allemands.', NULL, 4),
('Guerre de Sept Ans', 'guerre-de-sept-ans-allemagne-AL', '1756-01-01', '1763-02-15', 'La guerre de Sept Ans oppose notamment la Prusse à l''Autriche et à leurs alliés dans un conflit qui redéfinit l''équilibre des puissances européennes.', NULL, 6),
('Dissolution du Saint-Empire romain germanique', 'dissolution-saint-empire-romain-germanique', '1806-08-06', '1806-08-06', 'François II renonce à la couronne impériale, mettant officiellement fin au Saint-Empire romain germanique après près d''un millénaire d''existence.', NULL, 22),
('Bataille d''Iéna et d''Auerstaedt', 'bataille-iena-auerstaedt-AL', '1806-10-14', '1806-10-14', 'Les armées napoléoniennes remportent une victoire décisive contre les forces prussiennes lors des batailles d''Iéna et d''Auerstaedt.', NULL, 7),
('Guerres de libération contre Napoléon', 'guerres-liberation-contre-napoleon-AL', '1813-01-01', '1815-06-18', 'Les États allemands participent aux guerres de libération contre Napoléon, culminant avec la défaite française de 1815.', NULL, 6),
('Congrès de Vienne', 'congres-de-vienne-AL', '1814-09-01', '1815-06-09', 'Le Congrès de Vienne réorganise l''Europe après les guerres napoléoniennes et contribue à la nouvelle organisation politique des États allemands.', NULL, 14),
('Création de la Confédération germanique', 'creation-confederation-germanique', '1815-06-08', '1815-06-08', 'La Confédération germanique est créée lors du règlement européen issu du Congrès de Vienne et rassemble de nombreux États allemands.', NULL, 17),
('Révolution de 1848 dans les États allemands', 'revolution-1848-etats-allemands', '1848-03-01', '1849-07-01', 'Les révolutions de 1848 touchent les États allemands et provoquent une importante mobilisation en faveur des libertés et de l''unification.', NULL, 8),
('Parlement de Francfort', 'parlement-de-francfort', '1848-05-18', '1849-05-30', 'Le Parlement de Francfort se réunit à l''église Saint-Paul afin de travailler à l''unification politique et constitutionnelle des États allemands.', NULL, 22),
('Défaite de l''Autriche à Sadowa', 'bataille-de-sadowa-AL', '1866-07-03', '1866-07-03', 'La Prusse remporte une victoire décisive contre l''Autriche lors de la bataille de Sadowa pendant la guerre austro-prussienne.', NULL, 7),
('Création de la Confédération de l''Allemagne du Nord', 'creation-confederation-allemagne-du-nord', '1867-07-01', '1867-07-01', 'La Confédération de l''Allemagne du Nord est créée sous direction prussienne après la guerre austro-prussienne.', NULL, 17),
('Guerre franco-prussienne', 'guerre-franco-prussienne-AL', '1870-07-19', '1871-05-10', 'La guerre franco-prussienne oppose la France aux États allemands dirigés par la Prusse et accélère le processus d''unification allemande.', NULL, 6),
('Proclamation de l''Empire allemand', 'proclamation-empire-allemand', '1871-01-18', '1871-01-18', 'Guillaume Ier de Prusse est proclamé empereur allemand dans la galerie des Glaces du château de Versailles, marquant la création de l''Empire allemand.', NULL, 17),
('Traité de Francfort', 'traite-de-francfort-1871-AL', '1871-05-10', '1871-05-10', 'Le traité de Francfort met officiellement fin à la guerre franco-prussienne et confirme notamment la cession de l''Alsace et d''une partie de la Lorraine à l''Empire allemand.', NULL, 14),
('Début de la Première Guerre mondiale', 'debut-premiere-guerre-mondiale-allemagne-AL', '1914-08-01', '1914-08-01', 'L''Empire allemand déclare la guerre à la Russie dans le contexte de la crise de juillet, contribuant au déclenchement de la Première Guerre mondiale.', NULL, 6),
('Révolution allemande de 1918-1919', 'revolution-allemande-1918-1919', '1918-11-03', '1919-08-11', 'La révolution allemande entraîne la chute de la monarchie, l''abdication de Guillaume II et la création d''un régime républicain.', NULL, 8),
('Traité de Versailles', 'traite-de-versailles-allemagne-AL', '1919-06-28', '1919-06-28', 'Le traité de Versailles impose à l''Allemagne les conditions de paix mettant fin à la Première Guerre mondiale sur le front occidental.', NULL, 14),
('Adoption de la Constitution de Weimar', 'constitution-de-weimar', '1919-08-11', '1919-08-11', 'La Constitution de Weimar établit la République allemande et définit ses institutions démocratiques après la Première Guerre mondiale.', NULL, 22),
('Hyperinflation allemande', 'hyperinflation-allemande', '1923-01-01', '1923-11-01', 'L''Allemagne connaît une hyperinflation majeure en 1923, aggravée par les tensions économiques et l''occupation de la Ruhr.', NULL, 25),
('Putsch de la Brasserie', 'putsch-de-la-brasserie', '1923-11-08', '1923-11-09', 'Adolf Hitler et ses partisans tentent de renverser le gouvernement bavarois et le pouvoir allemand lors du putsch de la Brasserie à Munich.', NULL, 10),
('Grande Dépression en Allemagne', 'grande-depression-allemagne-AL', '1929-10-24', '1933-01-30', 'La crise économique mondiale frappe durement l''Allemagne et contribue à une profonde crise économique et politique durant la République de Weimar.', NULL, 25),
('Hitler devient chancelier', 'hitler-devient-chancelier', '1933-01-30', '1933-01-30', 'Le président Paul von Hindenburg nomme Adolf Hitler chancelier du Reich, ouvrant la voie à l''établissement du régime national-socialiste.', NULL, 22),
('Incendie du Reichstag', 'incendie-du-reichstag', '1933-02-27', '1933-02-27', 'Le bâtiment du Reichstag est incendié à Berlin. L''événement est suivi de mesures d''exception et d''une accélération de la mise au pas politique du régime nazi.', NULL, 10),
('Nuit de Cristal', 'nuit-de-cristal', '1938-11-09', '1938-11-10', 'Des violences antisémites coordonnées frappent les communautés juives dans l''Allemagne nazie et les territoires alors annexés.', NULL, 9),
('Invasion de la Pologne', 'invasion-de-la-pologne-1939-AL', '1939-09-01', '1939-10-06', 'L''Allemagne nazie envahit la Pologne, déclenchant la Seconde Guerre mondiale en Europe.', NULL, 13),
('Bataille de Stalingrad', 'bataille-de-stalingrad-AL', '1942-08-23', '1943-02-02', 'La bataille de Stalingrad se termine par la capitulation des forces allemandes encerclées et constitue un tournant majeur de la Seconde Guerre mondiale.', NULL, 7),
('Attentat du 20 juillet 1944', 'attentat-20-juillet-1944', '1944-07-20', '1944-07-20', 'Un groupe d''officiers allemands tente d''assassiner Adolf Hitler et de renverser le régime nazi lors de l''opération Walkyrie.', NULL, 10),
('Chute de Berlin', 'chute-de-berlin-AL', '1945-04-16', '1945-05-02', 'Les forces soviétiques lancent l''offensive finale contre Berlin et prennent la capitale du Reich au printemps 1945.', NULL, 7),
('Capitulation allemande', 'capitulation-allemande-1945-AL', '1945-05-07', '1945-05-08', 'L''Allemagne signe sa capitulation sans condition, mettant fin aux combats en Europe pendant la Seconde Guerre mondiale.', NULL, 14),
('Création de la République fédérale d''Allemagne', 'creation-rfa', '1949-05-23', '1949-05-23', 'La Loi fondamentale entre en vigueur et fonde la République fédérale d''Allemagne dans les zones d''occupation occidentales.', NULL, 17),
('Création de la République démocratique allemande', 'creation-rda', '1949-10-07', '1949-10-07', 'La République démocratique allemande est créée dans la zone d''occupation soviétique, officialisant la division politique de l''Allemagne.', NULL, 17),
('Construction du mur de Berlin', 'construction-mur-berlin', '1961-08-13', '1961-08-13', 'Les autorités est-allemandes ferment les passages entre Berlin-Est et Berlin-Ouest et commencent la construction du mur de Berlin.', NULL, 22),
('Chute du mur de Berlin', 'chute-mur-berlin', '1989-11-09', '1989-11-09', 'L''ouverture des postes-frontières de Berlin met fin au fonctionnement du mur et devient un symbole majeur de la fin de la division de l''Allemagne.', NULL, 8),
('Réunification allemande', 'reunification-allemande', '1990-10-03', '1990-10-03', 'La République démocratique allemande rejoint la République fédérale d''Allemagne, réalisant la réunification allemande.', NULL, 17);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
("Conquête romaine de l'Hispanie", 'conquete-romaine-de-l-hispanie', '0218-01-01', '0218-01-01', 'La République romaine conquiert progressivement la péninsule Ibérique au cours de plusieurs campagnes et intègre l''Hispanie au monde romain.', NULL, 12),
('Guerres cantabres', 'guerres-cantabres', '0029-01-01', '0029-01-01', 'Les guerres cantabres opposent les légions romaines aux peuples du nord de la péninsule et achèvent la conquête romaine de l''Hispanie.', NULL, 6),
('Début du royaume wisigoth en Hispanie', 'royaume-wisigoth-hispanie', '0507-01-01', '0507-01-01', 'Après la défaite de Vouillé, les Wisigoths établissent leur principal centre de pouvoir en Hispanie et développent le royaume de Tolède.', NULL, 16),
('Conversion de Reccarède au christianisme nicéen', 'conversion-de-reccarede', '0589-01-01', '0589-01-01', 'Le roi wisigoth Reccarède se convertit au christianisme nicéen lors du IIIe concile de Tolède, rapprochant les Wisigoths et les populations hispano-romaines.', NULL, 23),
('Conquête musulmane de la péninsule Ibérique', 'conquete-musulmane-peninsule-iberique-ES', '0711-01-01', '0718-01-01', 'Les forces musulmanes venues d''Afrique du Nord conquièrent une grande partie de la péninsule Ibérique et mettent fin au royaume wisigoth.', NULL, 13),
('Bataille de Covadonga', 'bataille-de-covadonga', '0722-01-01', '0722-01-01', 'La bataille de Covadonga oppose les forces du royaume des Asturies aux forces musulmanes et devient un épisode fondateur de la résistance chrétienne dans le nord de la péninsule.', NULL, 7),
('Émirat indépendant de Cordoue', 'emirat-de-cordoue', '0756-01-01', '0756-01-01', 'Abd al-Rahman Ier fonde l''émirat indépendant de Cordoue, qui devient le principal centre politique d''Al-Andalus.', NULL, 16),
('Califat de Cordoue', 'califat-de-cordoue', '0929-01-01', '0929-01-01', 'Abd al-Rahman III proclame le califat de Cordoue, qui atteint une puissance politique et culturelle majeure dans la péninsule Ibérique.', NULL, 16),
('Prise de Tolède', 'prise-de-tolede', '1085-05-25', '1085-05-25', 'Alphonse VI de León et de Castille conquiert Tolède, important centre politique et culturel d''Al-Andalus.', NULL, 12),
('Bataille de Las Navas de Tolosa', 'bataille-de-las-navas-de-tolosa', '1212-07-16', '1212-07-16', 'Une coalition de royaumes chrétiens remporte une victoire majeure contre les Almohades, accélérant l''expansion chrétienne vers le sud de la péninsule.', NULL, 7),
('Conquête de Séville', 'conquete-de-seville', '1248-11-23', '1248-11-23', 'Les forces de Ferdinand III conquièrent Séville, l''une des principales villes musulmanes de la péninsule.', NULL, 12),
('Union dynastique de Castille et d''Aragon', 'union-dynastique-castille-aragon', '1469-10-19', '1469-10-19', 'Le mariage d''Isabelle de Castille et de Ferdinand d''Aragon établit une union dynastique qui prépare la formation de la monarchie espagnole.', NULL, 3),
('Prise de Grenade', 'prise-de-grenade', '1492-01-02', '1492-01-02', 'Les Rois Catholiques prennent Grenade, mettant fin au royaume nasride et à la présence d''un dernier État musulman indépendant dans la péninsule.', NULL, 12),
('Décret de l''Alhambra', 'decret-de-l-alhambra', '1492-03-31', '1492-03-31', 'Les Rois Catholiques ordonnent l''expulsion des Juifs qui refusent la conversion au christianisme de leurs royaumes.', NULL, 22),
('Premier voyage de Christophe Colomb', 'premier-voyage-christophe-colomb-ES', '1492-08-03', '1492-12-31', 'Christophe Colomb quitte le port de Palos avec une expédition financée par les Rois Catholiques et atteint les Caraïbes en octobre 1492.', NULL, 18),
('Révolte des Comuneros', 'revolte-des-comuneros', '1520-01-01', '1521-04-23', 'La révolte des Comuneros oppose plusieurs villes de Castille au pouvoir de Charles Quint avant leur défaite à Villalar.', NULL, 9),
('Conquête de l''Empire aztèque', 'conquete-de-l-empire-azteque-ES', '1519-01-01', '1521-08-13', 'Les forces espagnoles dirigées par Hernán Cortés renversent l''Empire aztèque avec l''appui de nombreux alliés indigènes.', NULL, 12),
('Bataille de Lépante', 'bataille-de-lepante-ES', '1571-10-07', '1571-10-07', 'La Sainte Ligue, dont l''Espagne constitue la principale puissance, remporte une victoire navale contre la flotte ottomane en Méditerranée.', NULL, 7),
('Armada espagnole', 'armada-espagnole-ES', '1588-07-19', '1588-08-08', 'L''Armada espagnole tente d''envahir l''Angleterre mais subit une défaite navale et de lourdes pertes.', NULL, 7),
('Expulsion des Morisques', 'expulsion-des-morisques', '1609-09-22', '1614-01-01', 'La monarchie espagnole ordonne l''expulsion des Morisques, populations musulmanes converties au christianisme, entraînant leur départ massif des territoires espagnols.', NULL, 22),
('Guerre de Succession d''Espagne', 'guerre-de-succession-d-espagne-ES', '1701-07-09', '1714-09-11', 'La guerre de Succession d''Espagne oppose plusieurs puissances européennes autour de la succession au trône espagnol après la mort de Charles II.', NULL, 6),
('Décrets de Nueva Planta', 'decrets-de-nueva-planta', '1707-06-29', '1716-01-16', 'Les décrets de Nueva Planta réorganisent les institutions de plusieurs territoires de la monarchie espagnole et renforcent la centralisation autour de la Couronne.', NULL, 22),
('Traité d''Utrecht', 'traite-d-utrecht-ES', '1713-04-11', '1715-02-06', 'Les traités d''Utrecht mettent fin à une grande partie de la guerre de Succession d''Espagne et redéfinissent l''équilibre politique européen.', NULL, 14),
('Révolte de Madrid du 2 mai', 'revolte-de-madrid-2-mai', '1808-05-02', '1808-05-02', 'La population de Madrid se soulève contre l''occupation française, déclenchant une série d''insurrections dans la péninsule.', NULL, 9),
('Guerre d''Indépendance espagnole', 'guerre-d-independance-espagnole-ES', '1808-05-02', '1814-04-17', 'La guerre d''Indépendance espagnole oppose les forces françaises aux armées espagnoles, portugaises et britanniques dans le contexte des guerres napoléoniennes.', NULL, 6),
('Constitution de Cadix', 'constitution-de-cadix', '1812-03-19', '1812-03-19', 'Les Cortès de Cadix adoptent une constitution libérale qui établit notamment la souveraineté nationale et une monarchie constitutionnelle.', NULL, 22),
('Restauration de Ferdinand VII', 'restauration-ferdinand-vii', '1814-05-04', '1814-05-04', 'Ferdinand VII restaure la monarchie absolue après son retour en Espagne à la suite de la guerre contre Napoléon.', NULL, 5),
('Révolution de 1868', 'revolution-de-1868', '1868-09-19', '1868-10-03', 'La révolution de 1868 renverse Isabelle II et ouvre une période de transformations politiques connue sous le nom de Sexenio démocratique.', NULL, 8),
('Première République espagnole', 'premiere-republique-espagnole', '1873-02-11', '1874-12-29', 'La Première République espagnole est proclamée après l''abdication d''Amédée Ier et connaît une période d''instabilité politique et militaire.', NULL, 22),
('Restauration des Bourbons', 'restauration-des-bourbons', '1874-12-29', '1874-12-29', 'Le pronunciamiento de Martínez Campos restaure la monarchie des Bourbons avec l''accession d''Alphonse XII au trône.', NULL, 5),
('Guerre hispano-américaine', 'guerre-hispano-americaine-ES', '1898-04-21', '1898-08-13', 'La guerre hispano-américaine entraîne la défaite de l''Espagne et la perte de Cuba, de Porto Rico, de Guam et des Philippines.', NULL, 6),
('Coup d''État de Primo de Rivera', 'coup-etat-primo-de-rivera', '1923-09-13', '1923-09-13', 'Le général Miguel Primo de Rivera prend le pouvoir lors d''un coup d''État avec l''appui du roi Alphonse XIII.', NULL, 10),
('Proclamation de la Deuxième République espagnole', 'proclamation-deuxieme-republique-espagnole', '1931-04-14', '1931-04-14', 'Après les élections municipales de 1931, la monarchie s''effondre et la Deuxième République espagnole est proclamée.', NULL, 22),
('Guerre civile espagnole', 'guerre-civile-espagnole-ES', '1936-07-17', '1939-04-01', 'La guerre civile espagnole oppose les forces républicaines aux forces nationalistes dirigées par Francisco Franco et entraîne une profonde rupture politique et sociale.', NULL, 6),
('Bombardement de Guernica', 'bombardement-de-guernica-ES', '1937-04-26', '1937-04-26', 'Guernica est bombardée par la Légion Condor allemande et l''aviation légionnaire italienne pendant la guerre civile espagnole.', NULL, 20),
('Fin de la guerre civile espagnole', 'fin-guerre-civile-espagnole', '1939-04-01', '1939-04-01', 'La victoire des forces franquistes met fin à la guerre civile espagnole et établit durablement le régime de Franco.', NULL, 6),
('Début de la dictature franquiste', 'debut-dictature-franquiste', '1939-04-01', '1939-04-01', 'Francisco Franco établit un régime autoritaire qui dirige l''Espagne jusqu''à sa mort en 1975.', NULL, 5),
('Admission de l''Espagne à l''ONU', 'admission-espagne-onu-ES', '1955-12-14', '1955-12-14', 'L''Espagne rejoint l''Organisation des Nations unies, marquant son intégration progressive dans les institutions internationales après une période d''isolement.', NULL, 22),
('Mort de Francisco Franco', 'mort-de-francisco-franco', '1975-11-20', '1975-11-20', 'La mort de Francisco Franco met fin à près de quatre décennies de dictature et ouvre la voie à la transition démocratique espagnole.', NULL, 2),
('Avènement de Juan Carlos Ier', 'avenement-juan-carlos-ier', '1975-11-22', '1975-11-22', 'Juan Carlos Ier devient roi d''Espagne après la mort de Franco et engage progressivement le pays dans une transition vers la démocratie.', NULL, 5),
('Premières élections démocratiques depuis 1936', 'premieres-elections-democratiques', '1977-06-15', '1977-06-15', 'Les élections générales de 1977 constituent les premières élections démocratiques nationales depuis la guerre civile.', NULL, 22),
('Constitution espagnole de 1978', 'constitution-espagnole-1978', '1978-12-06', '1978-12-06', 'La Constitution espagnole est approuvée par référendum et établit le cadre institutionnel de la monarchie parlementaire contemporaine.', NULL, 22),
('Tentative de coup d''État du 23-F', 'tentative-coup-etat-23-f', '1981-02-23', '1981-02-23', 'Des militaires tentent de renverser les institutions démocratiques lors du coup d''État du 23-F, qui échoue.', NULL, 10),
('Adhésion de l''Espagne aux Communautés européennes', 'adhesion-espagne-communaute-europeenne-ES', '1986-01-01', '1986-01-01', 'L''Espagne rejoint les Communautés européennes avec le Portugal, marquant son intégration dans la construction européenne.', NULL, 14),
('Jeux olympiques de Barcelone', 'jeux-olympiques-barcelone-ES', '1992-07-25', '1992-08-09', 'Barcelone accueille les Jeux olympiques d''été de 1992, événement international majeur pour l''Espagne et la ville.', NULL, 24),
('Adoption de l''euro en Espagne', 'adoption-euro-espagne-ES', '1999-01-01', '2002-01-01', 'L''Espagne adopte l''euro comme monnaie commune européenne, d''abord pour les transactions financières puis sous forme fiduciaire en 2002.', NULL, 25),
('Attentats de Madrid', 'attentats-de-madrid', '2004-03-11', '2004-03-11', 'Une série d''attentats coordonnés frappe plusieurs trains de banlieue à Madrid et provoque une importante crise nationale.', NULL, 20),
('Abdication de Juan Carlos Ier', 'abdication-juan-carlos-ier', '2014-06-18', '2014-06-18', 'Juan Carlos Ier abdique en faveur de son fils Felipe, qui lui succède comme roi d''Espagne.', NULL, 22),
('Proclamation de Felipe VI', 'proclamation-felipe-vi', '2014-06-19', '2014-06-19', 'Felipe VI prête serment devant les Cortès et devient roi d''Espagne après l''abdication de Juan Carlos Ier.', NULL, 4),
('Référendum sur l''indépendance de la Catalogne', 'referendum-independance-catalogne', '2017-10-01', '2017-10-01', 'Un référendum sur l''indépendance de la Catalogne est organisé par les autorités catalanes malgré son opposition par les institutions espagnoles.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Éruption du Vésuve et destruction de Pompéi', 'eruption-vesuve-pompei-IT', '0079-08-24', '0079-08-25', 'L''éruption du Vésuve ensevelit Pompéi, Herculanum et plusieurs localités de Campanie sous les cendres et les matériaux volcaniques.', NULL, 20),
('Édit de Milan', 'edit-de-milan-IT', '0313-02-01', '0313-02-01', 'Constantin et Licinius établissent la liberté de culte dans l''Empire romain et mettent fin aux persécutions officielles contre les chrétiens.', NULL, 23),
('Fondation de Constantinople', 'fondation-de-constantinople-IT', '0330-05-11', '0330-05-11', 'Constantin inaugure Constantinople comme nouvelle capitale impériale sur le site de l''ancienne Byzance.', NULL, 16),
('Chute de l''Empire romain d''Occident', 'chute-empire-romain-occident-IT', '0476-09-04', '0476-09-04', 'Odoacre dépose Romulus Augustule, événement traditionnellement considéré comme la fin de l''Empire romain d''Occident.', NULL, 22),
('Guerre des Goths en Italie', 'guerre-des-goths-italie-IT', '0535-01-01', '0554-01-01', 'L''Empire byzantin mène une longue guerre contre les Ostrogoths pour reprendre le contrôle de l''Italie.', NULL, 6),
('Invasion lombarde de l''Italie', 'invasion-lombarde-italie-IT', '0568-01-01', '0568-01-01', 'Les Lombards envahissent l''Italie et fondent un royaume qui contrôle une grande partie de la péninsule pendant plusieurs siècles.', NULL, 13),
('Fondation des États pontificaux', 'fondation-des-etats-pontificaux-IT', '0756-01-01', '0756-01-01', 'Les territoires remis à la papauté par Pépin le Bref forment la base territoriale des États pontificaux.', NULL, 16),
('Couronnement de Charlemagne', 'couronnement-de-charlemagne-IT', '0800-12-25', '0800-12-25', 'Charlemagne est couronné empereur d''Occident par le pape Léon III à Rome.', NULL, 4),
('Bataille de Legnano', 'bataille-de-legnano-IT', '1176-05-29', '1176-05-29', 'La Ligue lombarde remporte une victoire contre les forces de Frédéric Barberousse, renforçant l''autonomie des communes du nord de l''Italie.', NULL, 7),
('Bataille de Montaperti', 'bataille-de-montaperti-IT', '1260-09-04', '1260-09-04', 'Les forces gibelines de Sienne remportent une victoire majeure contre les Guelfes de Florence lors de la bataille de Montaperti.', NULL, 7),
('Dante achève la Divine Comédie', 'dante-divine-comedie-IT', '1321-01-01', '1321-01-01', 'Dante Alighieri achève la Divine Comédie, œuvre majeure de la littérature italienne et européenne.', NULL, 24),
('Peste noire en Italie', 'peste-noire-en-italie-IT', '1348-01-01', '1352-01-01', 'La peste noire atteint les villes italiennes et provoque une catastrophe démographique majeure.', NULL, 21),
('Début de la Renaissance italienne', 'debut-renaissance-italienne-IT', '1401-01-01', '1401-01-01', 'Les villes italiennes deviennent un centre majeur de renouveau artistique, intellectuel et culturel qui donnera naissance à la Renaissance.', NULL, 24),
('Concile de Florence', 'concile-de-florence-IT', '1439-01-01', '1445-01-01', 'Le concile de Florence tente de restaurer l''unité entre les Églises catholique et orthodoxe et se tient notamment à Florence.', NULL, 23),
('Découverte de l''Amérique par Christophe Colomb', 'decouverte-amerique-christophe-colomb-IT', '1492-10-12', '1492-10-12', 'Christophe Colomb, navigateur originaire de Gênes au service de la monarchie espagnole, atteint les Caraïbes lors de son premier voyage transatlantique.', NULL, 18),
('Sac de Rome', 'sac-de-rome-IT', '1527-05-06', '1527-05-06', 'Les troupes impériales de Charles Quint prennent et pillent Rome, provoquant un choc majeur dans l''Italie de la Renaissance.', NULL, 13),
('Sacre de Charles Quint à Bologne', 'sacre-charles-quint-bologne-IT', '1530-02-24', '1530-02-24', 'Charles Quint est couronné empereur par le pape Clément VII à Bologne, lors du dernier couronnement impérial célébré par un pape.', NULL, 4),
('Traité de Cateau-Cambrésis', 'traite-de-cateau-cambresis-IT', '1559-04-03', '1559-04-03', 'Le traité de Cateau-Cambrésis met fin aux guerres d''Italie et confirme la domination espagnole sur une grande partie de la péninsule.', NULL, 14),
('Procès de Galilée', 'proces-de-galilee-IT', '1633-06-22', '1633-06-22', 'Galilée est condamné par l''Inquisition romaine pour avoir soutenu l''héliocentrisme et est contraint d''abjurer.', NULL, 23),
('Unification de l''Italie', 'unification-de-l-italie-IT', '1848-01-01', '1871-09-20', 'Le Risorgimento conduit progressivement à l''unification politique de la péninsule et à la création du royaume d''Italie.', NULL, 22),
('Statuto Albertino', 'statuto-albertino-IT', '1848-03-04', '1848-03-04', 'Charles-Albert de Sardaigne promulgue le Statuto Albertino, constitution qui devient ensuite la loi fondamentale du royaume d''Italie.', NULL, 22),
('République romaine de 1849', 'republique-romaine-1849-IT', '1849-02-09', '1849-07-03', 'Une République romaine est proclamée à Rome avant d''être renversée par l''intervention militaire française.', NULL, 22),
('Expédition des Mille', 'expedition-des-mille-IT', '1860-05-11', '1860-10-26', 'Giuseppe Garibaldi et ses volontaires conquièrent la Sicile et le royaume des Deux-Siciles, accélérant l''unification italienne.', NULL, 12),
('Proclamation du royaume d''Italie', 'proclamation-royaume-italie-IT', '1861-03-17', '1861-03-17', 'Victor-Emmanuel II est proclamé roi d''Italie et le royaume d''Italie est officiellement créé.', NULL, 22),
('Annexion de la Vénétie', 'annexion-de-la-venetie-IT', '1866-10-19', '1866-10-19', 'La Vénétie est rattachée au royaume d''Italie après la guerre austro-prussienne et le conflit italo-autrichien.', NULL, 12),
('Prise de Rome', 'prise-de-rome-IT', '1870-09-20', '1870-09-20', 'Les troupes italiennes entrent dans Rome et mettent fin au pouvoir temporel du pape sur la ville, qui devient la capitale du royaume d''Italie.', NULL, 12),
('Révolution industrielle en Italie', 'revolution-industrielle-italie-IT', '1870-01-01', '1914-01-01', 'L''industrialisation transforme progressivement l''économie italienne, notamment dans le nord du pays avec le développement de l''industrie, des chemins de fer et des grandes villes industrielles.', NULL, 24),
('Triplice', 'triplice-IT', '1882-05-20', '1882-05-20', 'L''Italie rejoint l''Allemagne et l''Autriche-Hongrie dans la Triple-Alliance, concluant un système d''alliance militaire au cœur de l''Europe.', NULL, 15),
('Tremblement de terre de Messine', 'tremblement-terre-messine-IT', '1908-12-28', '1908-12-28', 'Un séisme suivi d''un tsunami dévaste Messine et Reggio de Calabre et provoque une catastrophe majeure dans le sud de l''Italie.', NULL, 20),
('Début de la Première Guerre mondiale pour l''Italie', 'entree-italie-premiere-guerre-mondiale-IT', '1915-05-23', '1915-05-23', 'L''Italie déclare la guerre à l''Autriche-Hongrie et entre dans la Première Guerre mondiale aux côtés des puissances de l''Entente.', NULL, 6),
('Bataille de Caporetto', 'bataille-de-caporetto-IT', '1917-10-24', '1917-11-19', 'Les forces austro-hongroises et allemandes infligent une lourde défaite à l''armée italienne lors de la bataille de Caporetto.', NULL, 7),
('Traité de Saint-Germain-en-Laye', 'traite-saint-germain-italie-IT', '1919-09-10', '1919-09-10', 'Le traité de Saint-Germain-en-Laye réorganise les territoires de l''ancien Empire austro-hongrois et accorde notamment à l''Italie plusieurs territoires.', NULL, 14),
('Marche sur Rome', 'marche-sur-rome-IT', '1922-10-27', '1922-10-29', 'Les fascistes de Benito Mussolini organisent la marche sur Rome, après laquelle le roi Victor-Emmanuel III charge Mussolini de former le gouvernement.', NULL, 10),
('Accords du Latran', 'accords-du-latran-IT', '1929-02-11', '1929-02-11', 'Les accords du Latran règlent la question romaine, reconnaissent la souveraineté de la Cité du Vatican et établissent les relations entre l''Italie et le Saint-Siège.', NULL, 14),
('Invasion de l''Éthiopie', 'invasion-de-l-ethiopie-IT', '1935-10-03', '1936-05-05', 'L''Italie fasciste envahit l''Éthiopie et annexe le pays après une campagne militaire condamnée par la Société des Nations.', NULL, 13),
('Alliance entre l''Italie et l''Allemagne', 'pacte-d-acier-IT', '1939-05-22', '1939-05-22', 'L''Italie fasciste et l''Allemagne nazie signent le pacte d''Acier, renforçant leur alliance militaire et politique.', NULL, 15),
('Entrée de l''Italie dans la Seconde Guerre mondiale', 'entree-italie-seconde-guerre-mondiale-IT', '1940-06-10', '1940-06-10', 'L''Italie déclare la guerre à la France et au Royaume-Uni et entre dans la Seconde Guerre mondiale aux côtés de l''Allemagne.', NULL, 6),
('Chute de Mussolini', 'chute-de-mussolini-IT', '1943-07-25', '1943-07-25', 'Le Grand Conseil du fascisme provoque la chute de Benito Mussolini, qui est destitué et arrêté sur ordre du roi Victor-Emmanuel III.', NULL, 10),
('Armistice de Cassibile', 'armistice-de-cassibile-IT', '1943-09-03', '1943-09-03', 'Le royaume d''Italie signe secrètement un armistice avec les Alliés, annoncé publiquement le 8 septembre 1943.', NULL, 14),
('République sociale italienne', 'republique-sociale-italienne-IT', '1943-09-23', '1945-04-25', 'Mussolini établit la République sociale italienne dans le nord de l''Italie sous la protection militaire de l''Allemagne nazie.', NULL, 22),
('Libération de Rome', 'liberation-de-rome-IT', '1944-06-04', '1944-06-04', 'Les forces alliées entrent dans Rome et libèrent la capitale italienne de l''occupation allemande.', NULL, 12),
('Référendum institutionnel italien', 'referendum-institutionnel-italien-IT', '1946-06-02', '1946-06-02', 'Les Italiens votent par référendum pour choisir entre la monarchie et la république, la République italienne étant proclamée à la suite du scrutin.', NULL, 22),
('Constitution de la République italienne', 'constitution-republique-italienne-IT', '1948-01-01', '1948-01-01', 'La Constitution de la République italienne entre en vigueur et établit les principes et institutions de la nouvelle République.', NULL, 22),
('Adhésion de l''Italie aux Communautés européennes', 'adhesion-italie-communaute-europeenne-IT', '1957-03-25', '1957-03-25', 'L''Italie signe les traités de Rome avec cinq autres États européens, participant à la création de la Communauté économique européenne et d''Euratom.', NULL, 14),
('Catastrophe du Vajont', 'catastrophe-vajont-IT', '1963-10-09', '1963-10-09', 'Un gigantesque glissement de terrain dans le réservoir du Vajont provoque une vague qui dévaste plusieurs localités et fait près de deux mille victimes.', NULL, 20),
('Séisme d''Irpinia', 'seisme-irpinia-IT', '1980-11-23', '1980-11-23', 'Un puissant séisme frappe la Campanie et la Basilicate, causant d''importantes destructions et plusieurs milliers de victimes.', NULL, 20),
('Traité de Maastricht et création de l''Union européenne', 'traite-maastricht-union-europeenne-IT', '1992-02-07', '1993-11-01', 'Le traité de Maastricht est signé puis entre en vigueur, créant officiellement l''Union européenne, dont l''Italie est membre.', NULL, 14),
('Adoption de l''euro en Italie', 'adoption-euro-italie-IT', '1999-01-01', '2002-01-01', 'L''Italie adopte l''euro comme monnaie commune européenne, d''abord pour les transactions financières puis sous forme fiduciaire en 2002.', NULL, 25),
('Séisme de L''Aquila', 'seisme-laquila-IT', '2009-04-06', '2009-04-06', 'Un puissant séisme frappe la région des Abruzzes et provoque d''importantes destructions dans la ville de L''Aquila et ses environs.', NULL, 20),
('Expo 2015 à Milan', 'expo-2015-milan-IT', '2015-05-01', '2015-10-31', 'Milan accueille l''Exposition universelle de 2015, consacrée notamment aux enjeux de l''alimentation et du développement durable.', NULL, 16);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Arrivée des Romains dans la péninsule Ibérique', 'arrivee-romains-peninsule-iberique', '0218-01-01', '0218-12-31', 'Les armées romaines interviennent dans la péninsule Ibérique pendant la deuxième guerre punique, amorçant la romanisation progressive du territoire correspondant à l''actuel Portugal.', NULL, 12),
('Fondation de la province romaine de Lusitanie', 'fondation-province-lusitanie', '0015-01-01', '0015-12-31', 'Rome organise une partie de ses territoires ibériques en province de Lusitanie, dont le centre administratif se situe à Emerita Augusta.', NULL, 17),
('Invasion des Suèves dans la péninsule Ibérique', 'invasion-sueves-peninsule-iberique', '0409-01-01', '0409-12-31', 'Les Suèves pénètrent dans la péninsule Ibérique et fondent un royaume qui englobe une partie du nord-ouest de l''actuel Portugal.', NULL, 13),
('Fondation du royaume suève', 'fondation-royaume-sueve', '0411-01-01', '0411-12-31', 'Les Suèves établissent un royaume indépendant en Galice et dans le nord-ouest de la péninsule Ibérique, avec Braga comme centre politique majeur.', NULL, 16),
('Conquête wisigothe du royaume suève', 'conquete-wisigothe-royaume-sueve', '0585-01-01', '0585-12-31', 'Le roi wisigoth Léovigild conquiert le royaume suève et intègre ses territoires à la monarchie wisigothique.', NULL, 12),
('Invasion musulmane de la péninsule Ibérique', 'invasion-musulmane-peninsule-iberique', '0711-07-01', '0716-12-31', 'Les forces arabo-berbères conquièrent une grande partie de la péninsule Ibérique, plaçant le territoire portugais sous domination islamique progressive.', NULL, 13),
('Conquête chrétienne de Porto', 'conquete-chretienne-porto', '0868-01-01', '0868-12-31', 'Les forces chrétiennes reprennent Porto et consolident leur présence au nord du futur Portugal.', NULL, 12),
('Création du comté de Portugal', 'creation-comte-portugal', '0868-01-01', '0868-12-31', 'Le comté de Portugal est organisé dans le cadre de l''expansion du royaume des Asturies et devient une entité politique frontalière importante.', NULL, 16),
('Henri de Bourgogne reçoit le comté de Portugal', 'henri-bourgogne-comte-portugal', '1096-01-01', '1096-12-31', 'Henri de Bourgogne reçoit le comté de Portugal du roi Alphonse VI de León et de Castille, posant les bases de la future dynastie portugaise.', NULL, 22),
('Bataille d''Ourique', 'bataille-ourique', '1139-07-25', '1139-07-25', 'Alphonse Henriques remporte une victoire majeure contre les forces musulmanes et est acclamé roi par ses troupes selon la tradition portugaise.', NULL, 7),
('Traité de Zamora', 'traite-zamora-PT', '1143-10-05', '1143-10-05', 'Le traité de Zamora marque la reconnaissance par Alphonse VII de León et de Castille du titre royal d''Alphonse Henriques.', NULL, 14),
('Conquête de Lisbonne', 'conquete-lisbonne', '1147-10-25', '1147-10-25', 'Les forces portugaises d''Alphonse Henriques, aidées par des croisés européens, reprennent Lisbonne aux Almoravides.', NULL, 12),
('Conquête de Santarém', 'conquete-santarem', '1147-03-15', '1147-03-15', 'Alphonse Henriques s''empare de Santarém, renforçant la position portugaise dans la vallée du Tage.', NULL, 12),
('Reconnaissance pontificale du royaume du Portugal', 'reconnaissance-pontificale-royaume-portugal', '1179-05-23', '1179-05-23', 'La bulle Manifestis Probatum du pape Alexandre III reconnaît officiellement le royaume du Portugal et Alphonse Henriques comme roi.', NULL, 23),
('Bataille de Las Navas de Tolosa', 'bataille-las-navas-tolosa-PT', '1212-07-16', '1212-07-16', 'Les armées chrétiennes, auxquelles participent des forces portugaises, infligent une défaite majeure aux Almohades dans la péninsule Ibérique.', NULL, 7),
('Conquête de l''Algarve', 'conquete-algarve', '1249-01-01', '1249-12-31', 'Alphonse III achève la conquête chrétienne de l''Algarve en prenant plusieurs villes musulmanes, dont Faro, Loulé et Albufeira.', NULL, 12),
('Cortes de Leiria', 'cortes-leiria', '1254-01-01', '1254-12-31', 'Les Cortes de Leiria réunissent des représentants de la noblesse, du clergé et des municipalités, marquant une étape importante dans l''organisation politique du royaume.', NULL, 22),
('Lisbonne devient capitale du Portugal', 'lisbonne-capitale-portugal', '1255-01-01', '1255-12-31', 'Lisbonne devient la capitale du royaume du Portugal sous le règne d''Alphonse III.', NULL, 22),
('Fondation de l''Université de Coimbra', 'fondation-universite-coimbra', '1290-03-01', '1290-03-01', 'Le roi Denis Ier crée l''Estudo Geral, institution à l''origine de l''Université de Coimbra.', NULL, 17),
('Traité d''Alcañices', 'traite-alcanices-PT', '1297-09-12', '1297-09-12', 'Le Portugal et la Castille fixent une grande partie de leur frontière commune par le traité d''Alcañices.', NULL, 14),
('Traité commercial entre le Portugal et l''Angleterre', 'traite-commercial-portugal-angleterre-PT', '1308-05-01', '1308-05-01', 'Le Portugal et l''Angleterre concluent un accord commercial favorisant les échanges entre les deux royaumes.', NULL, 14),
('Crise de succession portugaise de 1383-1385', 'crise-succession-portugal-1383-1385', '1383-12-01', '1385-08-14', 'Une crise dynastique oppose les partisans de Jean de Castille aux défenseurs de l''indépendance portugaise et conduit à l''avènement de la dynastie d''Aviz.', NULL, 22),
('Bataille d''Aljubarrota', 'bataille-aljubarrota-PT', '1385-08-14', '1385-08-14', 'L''armée portugaise, soutenue par des alliés anglais, défait les forces castillanes et consolide l''indépendance du Portugal.', NULL, 7),
('Traité de Windsor', 'traite-windsor-PT', '1386-05-09', '1386-05-09', 'Le Portugal et l''Angleterre concluent une alliance diplomatique et militaire durable, considérée comme l''une des plus anciennes alliances internationales encore en vigueur.', NULL, 15),
('Prise de Ceuta', 'prise-ceuta-PT', '1415-08-21', '1415-08-21', 'Les forces portugaises dirigées par Jean Ier s''emparent de Ceuta, marquant le début de l''expansion portugaise outre-mer.', NULL, 12),
('Découverte de Madère', 'decouverte-madere', '1419-01-01', '1419-12-31', 'Les navigateurs portugais João Gonçalves Zarco et Tristão Vaz Teixeira explorent et prennent possession de l''île de Madère.', NULL, 18),
('Dépassement du cap Bojador', 'depassement-cap-bojador', '1434-01-01', '1434-12-31', 'Gil Eanes franchit le cap Bojador, étape majeure de l''exploration maritime portugaise de la côte africaine.', NULL, 18),
('Prise de Constantinople par les Ottomans', 'prise-constantinople-PT', '1453-05-29', '1453-05-29', 'La prise de Constantinople par les Ottomans bouleverse les échanges entre l''Europe et l''Orient et contribue à stimuler les recherches de nouvelles routes maritimes portugaises.', NULL, 12),
('Conquête d''Alcácer Ceguer', 'conquete-alcacer-ceguer-PT', '1458-10-24', '1458-10-24', 'Les Portugais s''emparent d''Alcácer Ceguer sur la côte marocaine sous le règne d''Alphonse V.', NULL, 12),
('Bataille de Toro', 'bataille-toro-PT', '1476-03-01', '1476-03-01', 'Les forces portugaises affrontent les troupes castillanes lors de la guerre de succession de Castille.', NULL, 7),
('Traité d''Alcáçovas', 'traite-alcacovas-PT', '1479-09-04', '1479-09-04', 'Le traité d''Alcáçovas met fin à la guerre de succession de Castille et délimite certaines zones d''influence maritimes entre le Portugal et la Castille.', NULL, 14),
('Arrivée de Bartolomeu Dias au cap de Bonne-Espérance', 'bartolomeu-dias-cap-bonne-esperance-PT', '1488-02-03', '1488-02-03', 'Bartolomeu Dias atteint le cap de Bonne-Espérance, ouvrant la voie maritime vers l''océan Indien.', NULL, 18),
('Arrivée de Vasco de Gama en Inde', 'vasco-de-gama-arrivee-inde-PT', '1498-05-20', '1498-05-20', 'Vasco de Gama atteint Calicut en Inde après avoir contourné l''Afrique, ouvrant une route maritime directe entre l''Europe et l''océan Indien.', NULL, 18),
('Découverte officielle du Brésil', 'decouverte-bresil-PT', '1500-04-22', '1500-04-22', 'La flotte de Pedro Álvares Cabral atteint les côtes du Brésil et en prend possession au nom du Portugal.', NULL, 18),
('Conquête de Malacca', 'conquete-malacca-PT', '1511-08-15', '1511-08-24', 'Les forces portugaises commandées par Afonso de Albuquerque conquièrent Malacca, centre stratégique du commerce asiatique.', NULL, 12),
('Séisme de Lisbonne', 'seisme-lisbonne', '1755-11-01', '1755-11-01', 'Un puissant séisme, suivi d''un tsunami et d''incendies, dévaste Lisbonne et provoque une catastrophe majeure dans le royaume du Portugal.', NULL, 20),
('Première invasion française du Portugal', 'premiere-invasion-francaise-portugal-PT', '1807-11-19', '1807-12-01', 'Les troupes napoléoniennes envahissent le Portugal, entraînant le départ de la famille royale et de la cour vers le Brésil.', NULL, 13),
('Création du Royaume-Uni de Portugal, du Brésil et des Algarves', 'creation-royaume-uni-portugal-bresil-algarves-PT', '1815-12-16', '1815-12-16', 'Le prince régent Jean élève le Brésil au rang de royaume et crée le Royaume-Uni de Portugal, du Brésil et des Algarves.', NULL, 17),
('Révolution libérale de Porto', 'revolution-liberale-porto', '1820-08-24', '1820-08-24', 'Une révolution libérale éclate à Porto et réclame le retour de la cour royale ainsi qu''une constitution.', NULL, 8),
('Guerres libérales portugaises', 'guerres-liberales-portugal', '1828-01-01', '1834-05-26', 'Une guerre civile oppose les partisans de la monarchie constitutionnelle aux défenseurs de l''absolutisme de Michel Ier.', NULL, 6),
('Abolition de la peine de mort pour les crimes civils', 'abolition-peine-mort-portugal', '1867-07-01', '1867-07-01', 'Le Portugal abolit la peine de mort pour les crimes civils, devenant l''un des premiers pays européens à adopter cette mesure.', NULL, 22),
('Ultimatum britannique au Portugal', 'ultimatum-britannique-portugal-PT', '1890-01-11', '1890-01-11', 'Le Royaume-Uni impose au Portugal de renoncer à ses projets de liaison territoriale entre l''Angola et le Mozambique, provoquant une crise politique majeure.', NULL, 22),
('Régicide de Lisbonne', 'regicide-lisbonne', '1908-02-01', '1908-02-01', 'Le roi Charles Ier et le prince héritier Louis-Philippe sont assassinés à Lisbonne lors d''un attentat contre la famille royale.', NULL, 2),
('Révolution du 5 octobre 1910', 'revolution-5-octobre-1910', '1910-10-05', '1910-10-05', 'La monarchie portugaise est renversée et la Première République est proclamée.', NULL, 8),
('Bataille de la Lys', 'bataille-la-lys-PT', '1918-04-09', '1918-04-09', 'Les forces portugaises engagées sur le front occidental subissent une lourde défaite face aux troupes allemandes pendant la Première Guerre mondiale.', NULL, 7),
('Coup d''État militaire du 28 mai 1926', 'coup-etat-militaire-28-mai-1926', '1926-05-28', '1926-05-28', 'Un coup d''État militaire met fin à la Première République portugaise et ouvre la voie à une longue dictature.', NULL, 10),
('Institutionnalisation de l''Estado Novo', 'institutionnalisation-estado-novo', '1933-04-11', '1933-04-11', 'Une nouvelle constitution institutionnalise l''Estado Novo, régime autoritaire dirigé par António de Oliveira Salazar.', NULL, 22),
('Révolution des Œillets', 'revolution-oeillets', '1974-04-25', '1974-04-25', 'Un soulèvement militaire renverse l''Estado Novo et ouvre la voie à la démocratisation du Portugal.', NULL, 8),
('Adhésion du Portugal à la Communauté économique européenne', 'adhesion-portugal-cee', '1986-01-01', '1986-01-01', 'Le Portugal rejoint la Communauté économique européenne avec l''Espagne, intégrant durablement le projet européen.', NULL, 17),
('Adoption de l''euro au Portugal', 'adoption-euro-portugal', '1999-01-01', '1999-01-01', 'Le Portugal adopte l''euro comme monnaie officielle pour les transactions financières, avant la mise en circulation des billets et pièces en 2002.', NULL, 25);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Séisme de Dyrrachium', 'seisme-dyrrachium', '0346-01-01', '0346-12-31', 'Un puissant séisme frappe Dyrrachium, l’actuelle Durrës, et provoque d’importants dégâts dans la région.', NULL, 20),
('Fondation de la principauté d''Arbanon', 'fondation-principaute-arbanon', '1190-01-01', '1190-12-31', 'Progon établit la principauté d’Arbanon, considérée comme l’un des premiers États médiévaux dirigés par une dynastie albanaise.', NULL, 16),
('Bataille de Savra', 'bataille-savra-AL', '1385-09-18', '1385-09-18', 'Les forces ottomanes remportent la bataille de Savra près de Lushnjë, marquant le début de l’expansion ottomane durable dans les territoires albanais.', NULL, 7),
('Ligue de Lezhë', 'ligue-lezhe', '1444-03-02', '1444-03-02', 'Skanderbeg et plusieurs princes albanais forment à Lezhë une alliance destinée à coordonner la résistance contre l’expansion ottomane.', NULL, 15),
('Bataille de Torvioll', 'bataille-torvioll-AL', '1444-06-29', '1444-06-29', 'Les forces commandées par Skanderbeg remportent une importante victoire contre l’armée ottomane à Torvioll.', NULL, 7),
('Siège de Krujë', 'siege-kruje-AL', '1450-05-14', '1450-10-23', 'L’armée ottomane assiège Krujë, mais la garnison dirigée par Skanderbeg résiste et contraint les assiégeants à se retirer.', NULL, 7),
('Prise de Krujë par les Ottomans', 'prise-kruje-AL', '1478-06-01', '1478-06-01', 'Après plusieurs décennies de résistance, Krujë tombe aux mains des Ottomans et la résistance organisée de la principauté de Skanderbeg s’achève progressivement.', NULL, 12),
('Prise de Shkodër par les Ottomans', 'prise-shkoder-AL', '1479-01-25', '1479-01-25', 'La République de Venise cède Shkodër aux Ottomans après le siège de la ville, consolidant la domination ottomane sur les territoires albanais.', NULL, 12),
('Création de la Ligue de Prizren', 'ligue-prizren', '1878-06-10', '1878-06-10', 'Des représentants albanais réunis à Prizren fondent la Ligue de Prizren afin de défendre l’intégrité territoriale et les intérêts politiques des populations albanaises.', NULL, 17),
('Ouverture de la première école normale albanaise', 'premiere-ecole-normale-albanaise', '1887-03-07', '1887-03-07', 'L’école de Korçë ouvre ses portes et devient un important centre de formation et de diffusion de l’enseignement en langue albanaise.', NULL, 24),
('Congrès de Manastir et adoption de l''alphabet latin', 'congres-manastir-alphabet-latin', '1908-11-14', '1908-11-22', 'Le Congrès de Manastir réunit des intellectuels albanais et contribue à établir l’alphabet latin comme base commune de l’écriture albanaise.', NULL, 24),
('Révolte albanaise de 1912', 'revolte-albanaise-1912', '1912-01-01', '1912-09-04', 'Une vaste insurrection albanaise contre le pouvoir ottoman obtient plusieurs concessions et accélère le processus menant à l’indépendance.', NULL, 9),
('Première Guerre balkanique', 'premiere-guerre-balkanique-AL', '1912-10-08', '1913-05-30', 'La Première Guerre balkanique oppose la Ligue balkanique à l’Empire ottoman et entraîne l’occupation de plusieurs territoires albanais.', NULL, 6),
('Déclaration d''indépendance de l''Albanie', 'declaration-independance-albanie', '1912-11-28', '1912-11-28', 'L’Assemblée nationale réunie à Vlorë proclame l’indépendance de l’Albanie et met en place un gouvernement provisoire dirigé par Ismail Qemali.', NULL, 11),
('Traité de Londres et reconnaissance de l''Albanie', 'traite-londres-albanie-AL', '1913-05-30', '1913-05-30', 'Le traité de Londres met fin à la Première Guerre balkanique et contribue à définir le territoire du nouvel État albanais.', NULL, 14),
('Arrivée du prince Guillaume de Wied', 'arrivee-guillaume-wied', '1914-03-07', '1914-03-07', 'Le prince Guillaume de Wied arrive à Durrës pour prendre la tête de la nouvelle principauté d’Albanie.', NULL, 4),
('Guerre de Vlora', 'guerre-vlora', '1920-06-04', '1920-08-02', 'Les forces albanaises affrontent les troupes italiennes autour de Vlora et obtiennent leur retrait de la région.', NULL, 6),
('Proclamation de la République albanaise', 'proclamation-republique-albanie', '1925-01-21', '1925-01-21', 'L’Assemblée constitutionnelle proclame la République albanaise après la prise du pouvoir par Ahmet Zogu.', NULL, 22),
('Invasion italienne de l''Albanie', 'invasion-italienne-albanie-AL', '1939-04-07', '1939-04-12', 'L’Italie fasciste envahit l’Albanie et contraint le roi Zog Ier à l’exil, intégrant le pays à l’empire italien.', NULL, 13),
('Chute du régime communiste en Albanie', 'chute-regime-communiste-albanie', '1990-12-08', '1992-03-22', 'Les manifestations étudiantes de décembre 1990 ouvrent la transition politique qui conduit à la fin du régime communiste et aux élections pluralistes de 1992.', NULL, 8);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Première mention écrite d''Andorre', 'premiere-mention-ecrite-andorre', '0843-01-01', '0843-12-31', 'Un acte de l’empereur carolingien Charles le Chauve mentionne les vallées d’Andorre parmi les possessions du comte Sunifred d’Urgell.', NULL, 18),
('Établissement de la coseigneurie d''Andorre', 'coseigneurie-andorre', '1278-09-08', '1278-09-08', 'Le premier paréage d’Andorre établit une souveraineté partagée entre l’évêque d’Urgell et le comte de Foix, fondement du système politique andorran.', NULL, 14),
('Second paréage d''Andorre', 'second-pareage-andorre', '1288-11-06', '1288-11-06', 'Le second paréage complète l’accord de 1278 et précise les droits et obligations des deux coseigneurs d’Andorre.', NULL, 14),
('Création du Consell de la Terra', 'creation-consell-terra', '1419-01-01', '1419-12-31', 'L’évêque d’Urgell reconnaît officiellement le Consell de la Terra, institution représentative chargée de gérer les affaires communes des vallées.', NULL, 17),
('Annexion temporaire d''Andorre par la Couronne d''Aragon', 'annexion-andorre-couronne-aragon', '1396-01-01', '1396-12-31', 'Andorre est temporairement rattachée à la Couronne d’Aragon dans le contexte des conflits politiques de la fin du Moyen Âge.', NULL, 12),
('Seconde annexion temporaire d''Andorre par la Couronne d''Aragon', 'seconde-annexion-andorre-aragon', '1512-01-01', '1512-12-31', 'Andorre connaît une nouvelle période de rattachement à la Couronne d’Aragon avant le rétablissement de son régime de coseigneurie.', NULL, 12),
('Adoption du Manual Digest', 'adoption-manual-digest', '1748-01-01', '1748-12-31', 'Antoni Fiter i Rossell rédige le Manual Digest, importante compilation du droit, des usages et de l’histoire politique d’Andorre.', NULL, 24),
('Révolution française et maintien de la coseigneurie', 'revolution-francaise-coseigneurie-andorre-FR', '1789-07-14', '1799-11-09', 'La Révolution française entraîne la suppression temporaire des droits féodaux du coseigneur français sur Andorre, tandis que la principauté maintient ses institutions traditionnelles.', NULL, 8),
('Rétablissement des droits du coseigneur français', 'retablissement-coseigneur-francais', '1806-01-01', '1806-12-31', 'Napoléon rétablit les droits institutionnels du chef de l’État français comme coseigneur d’Andorre.', NULL, 22),
('Nouvelle Réforme d''Andorre', 'nouvelle-reforme-andorre', '1866-04-22', '1866-04-22', 'La Nouvelle Réforme transforme les institutions politiques andorranes, élargit le droit de vote aux chefs de maison et renforce les pouvoirs du Conseil général.', NULL, 22),
('Ouverture de la première route carrossable vers l''Espagne', 'premiere-route-andorre-espagne', '1914-01-01', '1914-12-31', 'Une première route relie Andorre à la Seu d’Urgell en Espagne, réduisant l’isolement géographique du pays et facilitant les échanges.', NULL, 17),
('Révolution andorrane de 1933', 'revolution-andorrane-1933', '1933-04-05', '1933-04-05', 'Le mouvement des Jeunes Andorrans s’empare du Parlement et réclame des réformes politiques et l’instauration du suffrage universel masculin.', NULL, 8),
('Occupation française d''Andorre', 'occupation-francaise-andorre-FR', '1933-08-01', '1933-08-01', 'La France envoie des gendarmes en Andorre dans le contexte des troubles politiques liés à la réforme électorale de 1933.', NULL, 13),
('Proclamation de Boris Ier d''Andorre', 'proclamation-boris-premier-andorre', '1934-07-06', '1934-07-20', 'Boris Skossyreff se proclame souverain d’Andorre avant d’être arrêté par les autorités espagnoles et expulsé du territoire.', NULL, 10),
('Guerre civile espagnole et présence française en Andorre', 'guerre-civile-espagnole-andorre-ES', '1936-07-17', '1939-04-01', 'Pendant la guerre civile espagnole, la France maintient un détachement de gendarmes en Andorre afin de prévenir les débordements du conflit sur le territoire.', NULL, 6),
('Neutralité d''Andorre pendant la Seconde Guerre mondiale', 'neutralite-andorre-seconde-guerre-mondiale', '1939-09-01', '1945-09-02', 'Andorre reste officiellement neutre pendant la Seconde Guerre mondiale et sert notamment de voie de passage pour des réseaux d’évasion à travers les Pyrénées.', NULL, 22),
('Création du premier gouvernement d''Andorre', 'premier-gouvernement-andorre', '1982-01-14', '1982-01-14', 'Le premier gouvernement distinct du pouvoir législatif entre en fonction sous la présidence d’Òscar Ribas Reig.', NULL, 22),
('Création du Conseil exécutif d''Andorre', 'creation-conseil-executif-andorre', '1981-01-01', '1981-12-31', 'La création du Conseil exécutif marque le début d’une série de réformes institutionnelles conduisant à la transformation politique du principat.', NULL, 17),
('Adoption de la Constitution d''Andorre', 'constitution-andorre', '1993-03-14', '1993-03-14', 'Les électeurs andorrans approuvent par référendum la première Constitution écrite du pays, qui établit Andorre comme un État souverain, démocratique et de droit.', NULL, 22),
('Admission d''Andorre à l''Organisation des Nations unies', 'admission-andorre-onu-AL', '1993-07-28', '1993-07-28', 'Andorre devient membre de l’Organisation des Nations unies, consacrant son intégration dans la communauté internationale.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Conquête romaine du Norique', 'conquete-romaine-norique-AU', '0015-01-01', '0015-12-31', 'Les Romains établissent leur contrôle sur le royaume celtique du Norique, correspondant en grande partie à l’Autriche actuelle.', NULL, 12),
('Fondation du camp militaire de Vindobona', 'fondation-vindobona', '0090-01-01', '0090-12-31', 'Les Romains établissent à Vindobona, l’actuelle Vienne, un important camp militaire sur le Danube.', NULL, 16),
('Guerres marcomanes', 'guerres-marcomanes-AU', '0166-01-01', '0180-12-31', 'Les guerres marcomanes opposent l’Empire romain à plusieurs peuples germaniques le long du Danube, notamment dans la région de l’actuelle Autriche.', NULL, 6),
('Mort de Marc Aurèle à Vindobona', 'mort-marc-aurele-vindobona', '0180-03-17', '0180-03-17', 'L’empereur romain Marc Aurèle meurt à Vindobona, probablement durant la campagne contre les peuples germaniques.', NULL, 2),
('Bataille de Pressburg', 'bataille-pressburg-AU', '0907-07-04', '0907-07-04', 'Les Magyars remportent une importante victoire contre l’armée bavaroise à proximité de Pressburg, consolidant leur domination dans le bassin danubien.', NULL, 7),
('Bataille du Lechfeld', 'bataille-lechfeld-AU', '0955-08-10', '0955-08-10', 'Otton Ier bat les Magyars au Lechfeld, mettant fin à leurs grandes incursions en Germanie et renforçant le pouvoir ottonien dans la région alpine.', NULL, 7),
('Création du margraviat d''Autriche', 'creation-margraviat-autriche', '0976-01-01', '0976-12-31', 'L’empereur Otton II confie le margraviat oriental à Léopold de Babenberg, origine de la dynastie qui gouvernera l’Autriche pendant plusieurs siècles.', NULL, 16),
('Élévation de l''Autriche au rang de duché', 'elevation-autriche-duche', '1156-09-17', '1156-09-17', 'Le Privilegium Minus élève l’Autriche au rang de duché et accorde d’importants privilèges à la maison de Babenberg.', NULL, 22),
('Début du règne des Habsbourg en Autriche', 'debut-regne-habsbourg-autriche', '1278-08-26', '1278-08-26', 'La victoire de Rodolphe Ier de Habsbourg sur Ottokar II de Bohême permet aux Habsbourg de s’établir durablement en Autriche.', NULL, 5),
('Fondation de l''université de Vienne', 'fondation-universite-vienne', '1365-03-12', '1365-03-12', 'Le duc Rodolphe IV fonde l’université de Vienne, l’une des plus anciennes universités du monde germanophone.', NULL, 16),
('Mariage de Maximilien Ier et de Marie de Bourgogne', 'mariage-maximilien-marie-bourgogne-AU', '1477-08-19', '1477-08-19', 'Le mariage de Maximilien de Habsbourg et de Marie de Bourgogne renforce considérablement la puissance dynastique des Habsbourg en Europe.', NULL, 3),
('Couronnement impérial de Maximilien Ier', 'couronnement-maximilien-empereur-AU', '1508-02-04', '1508-02-04', 'Maximilien Ier prend le titre d’empereur élu des Romains sans être couronné par le pape, inaugurant une nouvelle pratique impériale.', NULL, 4),
('Siège de Vienne par les Ottomans', 'siege-vienne-1529-AU', '1529-09-27', '1529-10-15', 'L’armée ottomane de Soliman le Magnifique assiège Vienne mais échoue à prendre la ville.', NULL, 7),
('Bataille de Vienne', 'bataille-vienne-1683-AU', '1683-09-12', '1683-09-12', 'Les forces de la monarchie des Habsbourg et leurs alliés battent l’armée ottomane devant Vienne.', NULL, 7),
('Grande guerre turque', 'grande-guerre-turque-AU', '1683-01-01', '1699-01-26', 'La monarchie des Habsbourg participe à la guerre de la Sainte-Ligue contre l’Empire ottoman, qui se termine par le traité de Karlowitz.', NULL, 6),
('Guerre de Succession d''Espagne', 'guerre-succession-espagne-AU', '1701-07-09', '1714-04-11', 'La monarchie des Habsbourg participe à la guerre de Succession d’Espagne contre la France et ses alliés.', NULL, 6),
('Pragmatique Sanction de 1713', 'pragmatique-sanction-1713', '1713-04-19', '1713-04-19', 'Charles VI promulgue la Pragmatique Sanction afin d’assurer l’indivisibilité des possessions des Habsbourg et la succession de sa descendance.', NULL, 22),
('Naissance de Marie-Thérèse d''Autriche', 'naissance-marie-therese-autriche', '1717-05-13', '1717-05-13', 'Marie-Thérèse, future archiduchesse d’Autriche et reine de Hongrie et de Bohême, naît à Vienne.', NULL, 1),
('Guerre de Succession d''Autriche', 'guerre-succession-autriche-AU', '1740-12-16', '1748-10-18', 'La succession de Marie-Thérèse déclenche un conflit européen au cours duquel la monarchie des Habsbourg défend ses possessions.', NULL, 6),
('Couronnement de Marie-Thérèse reine de Hongrie', 'couronnement-marie-therese-hongrie', '1741-06-25', '1741-06-25', 'Marie-Thérèse est couronnée reine de Hongrie à Presbourg pendant la guerre de Succession d’Autriche.', NULL, 4),
('Réformes de Joseph II', 'reformes-joseph-ii', '1780-01-01', '1790-02-20', 'Joseph II mène une vaste politique de réformes administratives, religieuses et sociales dans les territoires des Habsbourg.', NULL, 22),
('Guerres de la Révolution française', 'guerres-revolution-francaise-AU', '1792-04-20', '1802-03-25', 'La monarchie des Habsbourg participe aux guerres contre la France révolutionnaire.', NULL, 6),
('Bataille de Wagram', 'bataille-wagram-AU', '1809-07-05', '1809-07-06', 'Napoléon Ier bat les forces autrichiennes lors de la bataille de Wagram, près de Vienne.', NULL, 7),
('Traité de Schönbrunn', 'traite-schonbrunn-AU', '1809-10-14', '1809-10-14', 'L’Autriche signe avec la France le traité de Schönbrunn après sa défaite dans la guerre de la Cinquième Coalition.', NULL, 14),
('Congrès de Vienne', 'congres-vienne-AU', '1814-09-01', '1815-06-09', 'Le Congrès de Vienne réorganise l’Europe après les guerres napoléoniennes et fait de l’Autriche une puissance centrale du nouvel ordre européen.', NULL, 22),
('Création de la Confédération germanique', 'creation-confederation-germanique-AU', '1815-06-08', '1815-06-08', 'L’Acte final du Congrès de Vienne établit la Confédération germanique, présidée par l’Empire d’Autriche.', NULL, 17),
('Révolution autrichienne de 1848', 'revolution-autrichienne-1848', '1848-03-13', '1848-12-31', 'Les mouvements révolutionnaires de 1848 provoquent à Vienne la chute de Metternich et de profondes transformations politiques.', NULL, 8),
('Abdication de Ferdinand Ier d''Autriche', 'abdication-ferdinand-autriche', '1848-12-02', '1848-12-02', 'Ferdinand Ier abdique au profit de son neveu François-Joseph Ier au cours des bouleversements révolutionnaires de 1848.', NULL, 22),
('Compromis austro-hongrois', 'compromis-austro-hongrois', '1867-03-30', '1867-06-08', 'Le compromis de 1867 transforme l’Empire d’Autriche en double monarchie austro-hongroise.', NULL, 22),
('Couronnement de François-Joseph Ier roi de Hongrie', 'couronnement-francois-joseph-hongrie', '1867-06-08', '1867-06-08', 'François-Joseph Ier est couronné roi de Hongrie après la création de la monarchie austro-hongroise.', NULL, 4),
('Exposition universelle de Vienne', 'exposition-universelle-vienne', '1873-05-01', '1873-10-31', 'Vienne accueille une grande exposition universelle consacrée notamment aux réalisations industrielles, scientifiques et culturelles.', NULL, 24),
('Création de la Sécession viennoise', 'creation-secession-viennoise', '1897-04-03', '1897-04-03', 'Des artistes autrichiens fondent la Sécession viennoise en rupture avec les institutions artistiques traditionnelles.', NULL, 24),
('Assassinat de François-Ferdinand à Sarajevo', 'assassinat-francois-ferdinand-SI', '1914-06-28', '1914-06-28', 'L’assassinat de l’archiduc François-Ferdinand et de son épouse à Sarajevo déclenche la crise diplomatique qui précède la Première Guerre mondiale.', NULL, 2),
('Déclaration de guerre austro-hongroise à la Serbie', 'declaration-guerre-serbie-AU', '1914-07-28', '1914-07-28', 'L’Autriche-Hongrie déclare la guerre à la Serbie, ouvrant les hostilités de la Première Guerre mondiale.', NULL, 6),
('Première Guerre mondiale', 'premiere-guerre-mondiale-AU', '1914-07-28', '1918-11-11', 'L’Autriche-Hongrie combat aux côtés des Empires centraux avant la désintégration de la monarchie en 1918.', NULL, 6),
('Proclamation de la République d''Autriche allemande', 'proclamation-republique-autriche-allemande', '1918-11-12', '1918-11-12', 'Après la dissolution de l’Empire austro-hongrois, l’Assemblée provisoire proclame la République d’Autriche allemande.', NULL, 22),
('Traité de Saint-Germain-en-Laye', 'traite-saint-germain-autriche-AU', '1919-09-10', '1919-09-10', 'Le traité de Saint-Germain-en-Laye fixe les nouvelles frontières de l’Autriche et interdit notamment son union avec l’Allemagne sans accord international.', NULL, 14),
('Adoption de la Constitution fédérale autrichienne', 'constitution-federale-autriche', '1920-10-01', '1920-10-01', 'L’Autriche adopte sa Constitution fédérale, qui organise les institutions de la nouvelle république.', NULL, 22),
('Guerre civile autrichienne', 'guerre-civile-autrichienne', '1934-02-12', '1934-02-16', 'Des affrontements armés opposent les forces gouvernementales et les organisations socialistes dans plusieurs villes autrichiennes.', NULL, 6),
('Établissement de l''État corporatif autrichien', 'etat-corporatif-autrichien', '1934-05-01', '1934-05-01', 'Une nouvelle constitution transforme l’Autriche en État autoritaire corporatif sous la direction d’Engelbert Dollfuss.', NULL, 22),
('Assassinat d''Engelbert Dollfuss', 'assassinat-engelbert-dollfuss', '1934-07-25', '1934-07-25', 'Des putschistes nazis autrichiens assassinent le chancelier Engelbert Dollfuss lors d’une tentative de coup d’État.', NULL, 2),
('Anschluss de l''Autriche à l''Allemagne nazie', 'anschluss-autriche-DE', '1938-03-12', '1938-03-13', 'Les troupes allemandes entrent en Autriche et le pays est incorporé au Reich allemand après l’Anschluss.', NULL, 13),
('Seconde Guerre mondiale', 'seconde-guerre-mondiale-AU', '1939-09-01', '1945-09-02', 'L’Autriche, intégrée au Reich allemand depuis 1938, participe au conflit jusqu’à la défaite de l’Allemagne nazie en 1945.', NULL, 6),
('Libération de Vienne', 'liberation-vienne-AU', '1945-04-06', '1945-04-13', 'Les forces soviétiques s’emparent de Vienne après de violents combats contre les forces allemandes.', NULL, 7),
('Rétablissement de la République autrichienne', 'retablissement-republique-autrichienne', '1945-04-27', '1945-04-27', 'Les représentants des partis autrichiens proclament la restauration de la République d’Autriche après la fin du régime nazi.', NULL, 22),
('Traité d''État autrichien', 'traite-etat-autrichien-AU', '1955-05-15', '1955-05-15', 'Le traité d’État autrichien met fin au régime d’occupation alliée et rétablit la pleine souveraineté de l’Autriche.', NULL, 14),
('Déclaration de neutralité permanente de l''Autriche', 'neutralite-permanente-autriche', '1955-10-26', '1955-10-26', 'Le Parlement autrichien adopte la loi constitutionnelle établissant la neutralité permanente de l’Autriche.', NULL, 22),
('Adhésion de l''Autriche à l''Union européenne', 'adhesion-autriche-union-europeenne-UE', '1995-01-01', '1995-01-01', 'L’Autriche devient membre de l’Union européenne avec la Finlande et la Suède.', NULL, 22),
('Adoption de l''euro en Autriche', 'adoption-euro-autriche-UE', '1999-01-01', '1999-01-01', 'L’Autriche adopte l’euro comme monnaie officielle pour les transactions financières avant la mise en circulation des pièces et billets en 2002.', NULL, 25),
('Mise en circulation de l''euro en Autriche', 'mise-circulation-euro-autriche-UE', '2002-01-01', '2002-01-01', 'Les pièces et billets en euros remplacent progressivement le schilling autrichien comme monnaie fiduciaire.', NULL, 25);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Fondation de la principauté de Polotsk', 'fondation-principaute-polotsk', '0862-01-01', '0862-12-31', 'La principauté de Polotsk devient un important centre politique des terres correspondant au nord de la Biélorussie.', NULL, 16),
('Christianisation des terres de la Rus', 'christianisation-rus-BI', '0988-01-01', '0988-12-31', 'La christianisation de la Rus kiévienne étend le christianisme orthodoxe aux territoires biélorusses.', NULL, 23),
('Fondation de Minsk', 'fondation-minsk', '1067-01-01', '1067-12-31', 'Minsk est mentionnée pour la première fois dans les sources historiques à l’occasion de la bataille de la Nemiga.', NULL, 16),
('Intégration de Navahrudak au grand-duché de Lituanie', 'integration-navahrudak-grand-duche-lituanie', '1250-01-01', '1250-12-31', 'Navahrudak devient un centre majeur du grand-duché de Lituanie.', NULL, 12),
('Bataille de Grunwald', 'bataille-grunwald-BI', '1410-07-15', '1410-07-15', 'Les forces polono-lituaniennes battent l’ordre Teutonique lors d’une grande bataille d’Europe orientale.', NULL, 7),
('Bataille d’Orcha', 'bataille-orcha-BI', '1514-09-08', '1514-09-08', 'Les forces du grand-duché de Lituanie remportent une victoire contre la Moscovie près d’Orcha.', NULL, 7),
('Premier Statut de Lituanie', 'premier-statut-lituanie', '1529-01-01', '1529-12-31', 'Le premier Statut de Lituanie codifie le droit du grand-duché dans une langue ruthène.', NULL, 22),
('Union de Lublin', 'union-lublin-BI', '1569-07-01', '1569-07-01', 'L’union de Lublin crée la République des Deux Nations, réunissant la Pologne et le grand-duché de Lituanie.', NULL, 14),
('Deuxième partage de la République des Deux Nations', 'deuxieme-partage-republique-deux-nations-BI', '1793-01-23', '1793-01-23', 'Le deuxième partage entraîne l’annexion de vastes territoires biélorusses par l’Empire russe.', NULL, 12),
('Insurrection de Kościuszko', 'insurrection-kosciuszko-BI', '1794-03-24', '1794-11-16', 'L’insurrection de Kościuszko contre les puissances partageant la République des Deux Nations touche également les territoires biélorusses.', NULL, 9),
('Guerre franco-russe de 1812', 'guerre-franco-russe-1812-BI', '1812-06-24', '1812-12-14', 'La campagne de Napoléon contre la Russie traverse largement les territoires de l’actuelle Biélorussie.', NULL, 6),
('Soulèvement de Kalinowski', 'soulevement-kalinowski', '1863-01-22', '1864-06-18', 'Kastus Kalinowski dirige une insurrection contre la domination de l’Empire russe dans les anciennes terres du grand-duché de Lituanie.', NULL, 9),
('Proclamation de la République populaire biélorusse', 'proclamation-republique-populaire-bielorusse', '1918-03-25', '1918-12-31', 'La Rada proclame la République populaire biélorusse pendant la période de bouleversements suivant la Première Guerre mondiale.', NULL, 11),
('Création de la République socialiste soviétique de Biélorussie', 'creation-rss-bielorussie', '1919-01-01', '1919-01-01', 'Les bolcheviks proclament la République socialiste soviétique de Biélorussie.', NULL, 17),
('Traité de Riga', 'traite-riga-BI', '1921-03-18', '1921-03-18', 'Le traité de Riga met fin à la guerre soviéto-polonaise et partage les territoires biélorusses entre la Pologne et la Russie soviétique.', NULL, 14),
